hints:
```
count letter frequencies in array of size 26
build frequency-of-frequencies map
if one distinct frequency value f with count c:
    return (f == 1) or (c == 1)
if two distinct frequency values f1 < f2 with counts c1, c2:
    return (f2 == f1 + 1 and c2 == 1) or (f1 == 1 and c1 == 1)
return false
```

code.cpp:
class Solution {
public:
    bool equalFrequency(string word) {
        int freq[26] = {0};
        for (char c : word) {
            freq[c - 'a']++;
        }
        int fc[101] = {0};
        for (int i = 0; i < 26; i++) {
            if (freq[i] > 0) {
                fc[freq[i]]++;
            }
        }
        int cnt = 0;
        int f1 = 0, c1 = 0, f2 = 0, c2 = 0;
        for (int f = 1; f <= 100; f++) {
            if (fc[f] > 0) {
                cnt++;
                if (cnt == 1) {
                    f1 = f;
                    c1 = fc[f];
                } else if (cnt == 2) {
                    f2 = f;
                    c2 = fc[f];
                }
            }
        }
        if (cnt == 1) {
            return f1 == 1 || c1 == 1;
        }
        if (cnt == 2) {
            if (f2 == f1 + 1 && c2 == 1) return true;
            if (f1 == 1 && c1 == 1) return true;
            return false;
        }
        return false;
    }
};
